const body = $input.first().json;
const alerts = body.alerts || [];
const alert = alerts[0] || {};
const labels = alert.labels || {};
const desc = (alert.annotations && (alert.annotations.description || alert.annotations.summary) || '').slice(0, 600);

return [{
  json: {
    alertName: labels.alertname || 'AI Service Error',
    instance: labels.instance || 'pocat-backend',
    severity: labels.severity || 'warning',
    description: desc,
    startTime: alert.startsAt || new Date().toISOString(),
    generatorURL: alert.generatorURL || '',
    geminiRequest: {
      model: 'gemini-2.0-flash',
      max_tokens: 300,
      messages: [
        {
          role: 'system',
          content: 'POCAT 카드 거래 플랫폼 AI 서비스 모니터링입니다. 간결하게 한국어로 3줄 이내 답변하세요.'
        },
        {
          role: 'user',
          content: 'AI 서비스 이상 감지\n알림명: ' + (labels.alertname || '') + '\n인스턴스: ' + (labels.instance || '') + '\n심각도: ' + (labels.severity || '') + '\n내용: ' + desc + '\n\n원인 추정, 영향 범위, 즉시 조치를 각 1줄로 답변하세요.'
        }
      ]
    }
  }
}];

const geminiResp = $json;
const analysis = (geminiResp.choices && geminiResp.choices[0] && geminiResp.choices[0].message && geminiResp.choices[0].message.content) || '분석 실패';
const prev = $('Parse Alert & Build Request').first().json;
const color = prev.severity === 'critical' ? 'danger' : 'warning';

return [{
  json: {
    slackPayload: {
      text: '🤖 *[AI 서비스 이상] ' + prev.alertName + '*',
      attachments: [{
        color: color,
        fields: [
          { title: '인스턴스', value: prev.instance || '-', short: true },
          { title: '심각도', value: prev.severity || '-', short: true },
          { title: '내용', value: prev.description || '-', short: false },
          { title: 'AI 분석', value: analysis, short: false }
        ],
        footer: 'POCAT Monitoring | ' + prev.startTime,
        footer_icon: 'https://grafana.com/favicon.ico'
      }]
    }
  }
}];
